import React, { useState } from 'react';
import { Toaster } from 'react-hot-toast';
import { AppProvider } from './context/AppContext';
import TablesView from './components/TablesView';
import KitchenView from './components/KitchenView';
import HistoryView from './components/HistoryView';
import StaffView from './components/StaffView';
import TutorialView from './components/TutorialView';

const NAV = [
  {
    id: 'tables',
    label: 'Stollar',
    icon: (
      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
          d="M3 10h18M3 14h18M10 3v18M14 3v18" />
      </svg>
    ),
  },
  {
    id: 'kitchen',
    label: 'Oshxona',
    icon: (
      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
          d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0" />
      </svg>
    ),
  },
  {
    id: 'history',
    label: 'Statistika',
    icon: (
      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
          d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
      </svg>
    ),
  },
  {
    id: 'staff',
    label: 'Xodimlar',
    icon: (
      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
          d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
      </svg>
    ),
  },
  {
    id: 'tutorial',
    label: 'Qo\'llanma',
    icon: (
      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
          d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
      </svg>
    ),
    highlight: true,
  },
];

const VIEWS = {
  tables: <TablesView />,
  kitchen: <KitchenView />,
  history: <HistoryView />,
  staff: <StaffView />,
  tutorial: <TutorialView />,
};

function Layout() {
  const [active, setActive] = useState('tables');

  return (
    <div className="min-h-screen bg-[#0a0d14] flex">
      {/* Sidebar */}
      <aside className="w-64 bg-[#0d1017] border-r border-white/[0.06] flex flex-col fixed inset-y-0 left-0 z-10">
        {/* Logo */}
        <div className="px-6 py-6 border-b border-white/[0.06]">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-violet-600 rounded-xl flex items-center justify-center">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                  d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
              </svg>
            </div>
            <div>
              <h1 className="text-white font-bold text-lg leading-none">BitePlate</h1>
              <p className="text-gray-600 text-xs mt-0.5">Restoran tizimi</p>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-3 py-4 space-y-1 overflow-y-auto">
          <p className="px-4 text-[10px] font-bold text-gray-700 uppercase tracking-widest mb-3">Bosh menyu</p>
          {NAV.map((item) => (
            <button
              key={item.id}
              onClick={() => setActive(item.id)}
              className={`nav-item ${active === item.id ? 'nav-item-active' : 'nav-item-inactive'} ${item.highlight && active !== item.id ? 'text-amber-500 hover:text-amber-400' : ''}`}
            >
              {item.icon}
              <span>{item.label}</span>
              {item.highlight && (
                <span className="ml-auto badge bg-amber-500/20 text-amber-400">Yangi</span>
              )}
            </button>
          ))}
        </nav>

        {/* Footer */}
        <div className="px-5 py-4 border-t border-white/[0.06]">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-violet-900/60 flex items-center justify-center text-violet-400 text-xs font-bold">
              BP
            </div>
            <div>
              <p className="text-gray-300 text-xs font-medium">Unit 27 — BTEC L5</p>
              <p className="text-gray-600 text-[10px]">OOP & Design Patterns</p>
            </div>
          </div>
        </div>
      </aside>

      {/* Main */}
      <main className="flex-1 ml-64 min-h-screen overflow-y-auto">
        {/* Top bar */}
        <div className="sticky top-0 z-10 bg-[#0a0d14]/80 backdrop-blur-xl border-b border-white/[0.06] px-8 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-white font-semibold text-base">
                {NAV.find((n) => n.id === active)?.label}
              </h2>
              <p className="text-gray-600 text-xs mt-0.5">BitePlate Restoran Boshqaruv Tizimi</p>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
              <span className="text-xs text-gray-500">Jonli</span>
            </div>
          </div>
        </div>

        {/* Page content */}
        <div className="p-8">
          {VIEWS[active]}
        </div>
      </main>
    </div>
  );
}

export default function App() {
  return (
    <AppProvider>
      <Toaster
        position="top-right"
        toastOptions={{
          style: {
            background: '#12161f',
            color: '#f1f5f9',
            border: '1px solid rgba(255,255,255,0.08)',
            borderRadius: '12px',
            fontSize: '14px',
          },
          success: { iconTheme: { primary: '#34d399', secondary: '#12161f' } },
          error: { iconTheme: { primary: '#f87171', secondary: '#12161f' } },
        }}
      />
      <Layout />
    </AppProvider>
  );
}
